  "/** @param {unknown} role */",
  "function sessionPermissionRules(role) {",
  "  if (!knownRole(role)) refuse(\"intent-invalid\", { field: \"role\" });",
  "  return [...ROLE_MCP_PERMISSION_RULES[role], `Bash(node ${ASSET_PATH} *)`];",
