  "      unexpressed += 1;",
  "      continue;",
  "    }",
  "    // 规则里的绝对路径以 `//` 开头（单个 `/` 是相对设置文件所在目录）。",
  "    for (const spelling of spellings) rules.add(`Edit(/${spelling}${suffix})`);",
  "  }",
  "  return { rules: [...rules], unexpressed };",
